"""Prototype of the memory-derived answer space and label grounding."""

from __future__ import annotations

import json
import re
from pathlib import Path

TAG = r"A-Za-z0-9_/一-鿿"
LEAD_TAG = re.compile(rf"^\s*\[{TAG}{{1,32}}\]")
TRAIL_TAG = re.compile(rf"(\[/?{TAG}{{1,32}}\]|<[^<>]{{1,32}}>)\s*$")
LEAD_IN = re.compile(r"^\s*[^\s:：\[\]<>]{1,12}[:：]")


def strip_annotation(text):
    text = (text or "").strip()
    changed = True
    while changed and text:
        changed = False
        m = LEAD_TAG.match(text)
        if m:
            text = text[m.end():].strip(); changed = True
        m = TRAIL_TAG.search(text)
        if m and m.end() == len(text):
            text = text[: m.start()].strip(); changed = True
    m = LEAD_IN.match(text)
    if m:
        text = text[m.end():].strip()
    return text


def split_wrapper(text):
    text = text or ""
    lead = ""
    m = LEAD_TAG.match(text)
    if m:
        lead = m.group(0); text = text[m.end():]
    tail = ""
    m = TRAIL_TAG.search(text)
    if m and m.end() == len(text):
        tail = m.group(0); text = text[: m.start()]
    return lead, text, tail


def _edits(a, b, cap):
    if abs(len(a) - len(b)) > cap:
        return cap + 1
    prev = list(range(len(b) + 1))
    for i, ca in enumerate(a, 1):
        cur = [i]
        for j, cb in enumerate(b, 1):
            cur.append(min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + (ca != cb)))
        if min(cur) > cap:
            return cap + 1
        prev = cur
    return prev[-1]


def derive_answer_space(targets, min_reuse=0.25):
    """Infer the strings answers are built from, and the separator that joins them."""
    answers = []
    for t in targets:
        core = strip_annotation(t)
        if core:
            answers.append(core)
    if not answers:
        return {"items": [], "separator": None}
    whole = set(answers)
    candidates = {}
    for core in answers:
        for ch in set(core):
            if not ch.isalnum() and not ch.isspace():
                candidates[ch] = candidates.get(ch, 0) + 1
    best = None
    for ch, seen in candidates.items():
        if seen < 2:
            continue
        pieces = [p.strip() for c in answers if ch in c for p in c.split(ch) if p.strip()]
        if not pieces:
            continue
        distinct = set(pieces)
        reuse = sum(1 for p in distinct if p in whole) / len(distinct)
        score = (reuse, seen)
        if best is None or score > best[0]:
            best = (score, ch, distinct)
    separator, items = None, whole
    if best is not None and best[0][0] >= min_reuse:
        separator, items = best[1], best[2] | whole
    return {"items": sorted(items), "separator": separator}


def snap(item, items, max_edits=1):
    item = item.strip()
    if not item or item in items:
        return item
    low = item.lower()
    best = None
    ties = 0
    for cand in items:
        d = _edits(low, cand.lower(), max_edits)
        if d > max_edits:
            continue
        key = (d, -len(cand))
        if best is None or key < best[0]:
            best = (key, cand); ties = 1
        elif key == best[0]:
            ties += 1
    return best[1] if best is not None and ties == 1 else item


def ground_answer(text, space, max_edits=1):
    items = space.get("items") or []
    if not items or not text:
        return text
    lead, body, tail = split_wrapper(text)
    separator = space.get("separator")
    if separator and separator in body:
        parts = body.split(separator)
        body = separator.join(snap(p, items, max_edits) for p in parts)
    else:
        body = snap(body, items, max_edits)
    return f"{lead}{body}{tail}"
